"""Constraint card parsers.

SPC: Single-point constraint (enforced displacement).
SPC1: Single-point constraint (zero or uniform value).
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import List, Tuple

from ..cards import nastran_int, nastran_float


@dataclass
class SPC:
    """Single-point constraint with enforced displacement.

    SPC     SID     G1      C1      D1      G2      C2      D2
    """
    sid: int = 0
    constraints: List[Tuple[int, str, float]] = field(default_factory=list)
    # Each tuple: (node_id, components_string, enforced_value)

    @property
    def type(self) -> str:
        return "SPC"

    @classmethod
    def from_fields(cls, fields: List[str]) -> SPC:
        spc = cls()
        spc.sid = nastran_int(fields[1])

        # Parse pairs of (G, C, D)
        i = 2
        while i + 2 < len(fields):
            g_str = fields[i].strip()
            c_str = fields[i + 1].strip()
            if not g_str:
                break
            nid = nastran_int(fields[i])
            comp = c_str
            disp = nastran_float(fields[i + 2])
            spc.constraints.append((nid, comp, disp))
            i += 3

        return spc


@dataclass
class SPC1:
    """Single-point constraint for multiple grids with same components.

    SPC1    SID     C       G1      G2      G3      G4      G5      G6
            G7      G8      ...
    """
    sid: int = 0
    components: str = ""   # Component string (e.g., "123456")
    node_ids: List[int] = field(default_factory=list)

    @property
    def type(self) -> str:
        return "SPC1"

    @classmethod
    def from_fields(cls, fields: List[str]) -> SPC1:
        spc = cls()
        spc.sid = nastran_int(fields[1])
        spc.components = fields[2].strip()

        # Check for THRU syntax
        node_strs = [f.strip() for f in fields[3:] if f.strip()]
        if len(node_strs) >= 3 and node_strs[1].upper() == "THRU":
            start = int(node_strs[0])
            end = int(node_strs[2])
            spc.node_ids = list(range(start, end + 1))
        else:
            for ns in node_strs:
                if ns and ns.upper() != "THRU":
                    try:
                        spc.node_ids.append(int(ns))
                    except ValueError:
                        pass

        return spc

