"""PARAM card parser.

PARAM sets global solution parameters.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any, List, Tuple

from ..cards import nastran_float


@dataclass
class PARAM:
    """Parameter card.

    PARAM   NAME    VALUE1  VALUE2
    """
    name: str = ""
    values: List[Any] = None

    def __post_init__(self):
        if self.values is None:
            self.values = []

    @classmethod
    def from_fields(cls, fields: List[str]) -> Tuple[str, Any]:
        """Parse PARAM and return (name, value) tuple."""
        name = fields[1].strip().upper()

        # Try to parse value as number first
        val_str = fields[2].strip() if len(fields) > 2 else ""
        if not val_str:
            return name, None

        # Try float
        try:
            val = nastran_float(val_str)
            # Check if it's actually an integer
            if "." not in val_str:
                return name, int(val)
            return name, val
        except (ValueError, IndexError):
            pass

        # Return as string
        return name, val_str

