"""DOF (Degree of Freedom) manager.

Maps structural grid point IDs and component numbers to global DOF indices.
Each grid point has 6 DOFs: T1, T2, T3, R1, R2, R3.
"""

from __future__ import annotations

from typing import Dict, List, Set, Tuple

import numpy as np


class DOFManager:
    """Manages the mapping between (node_id, component) and global DOF index.

    Components are numbered 1-6:
        1=T1 (x-translation), 2=T2 (y-translation), 3=T3 (z-translation)
        4=R1 (x-rotation), 5=R2 (y-rotation), 6=R3 (z-rotation)
    """

    def __init__(self, node_ids: List[int]) -> None:
        """Initialize DOF map for the given node IDs.

        Args:
            node_ids: Sorted list of all structural node IDs.
        """
        self._sorted_nids = sorted(node_ids)
        self._nid_to_index: Dict[int, int] = {
            nid: idx for idx, nid in enumerate(self._sorted_nids)
        }
        self._ndof_per_node = 6
        self._total_dof = len(self._sorted_nids) * self._ndof_per_node

    @property
    def total_dof(self) -> int:
        """Total number of DOFs in the model."""
        return self._total_dof

    @property
    def n_nodes(self) -> int:
        return len(self._sorted_nids)

    @property
    def node_ids(self) -> List[int]:
        return self._sorted_nids

    def get_dof(self, node_id: int, component: int) -> int:
        """Get global DOF index for a (node_id, component) pair.

        Args:
            node_id: Grid point ID.
            component: Component number (1-6).

        Returns:
            Global DOF index (0-based).
        """
        node_index = self._nid_to_index[node_id]
        return node_index * self._ndof_per_node + (component - 1)

    def get_node_dofs(self, node_id: int) -> List[int]:
        """Get all 6 global DOF indices for a node.

        Returns:
            List of 6 DOF indices [T1, T2, T3, R1, R2, R3].
        """
        node_index = self._nid_to_index[node_id]
        base = node_index * self._ndof_per_node
        return list(range(base, base + 6))

    def get_element_dofs(self, node_ids: List[int]) -> List[int]:
        """Get all DOF indices for an element (concatenation of node DOFs).

        Args:
            node_ids: List of node IDs for the element.

        Returns:
            Flat list of DOF indices.
        """
        dofs: List[int] = []
        for nid in node_ids:
            dofs.extend(self.get_node_dofs(nid))
        return dofs

    def get_constrained_dofs(
        self, spc_list: list, model_nodes: dict
    ) -> Tuple[Set[int], Dict[int, float]]:
        """Get the set of constrained DOFs from SPC/SPC1 entries.

        Also handles permanent SPCs from GRID PS field.

        Args:
            spc_list: List of SPC/SPC1 objects.
            model_nodes: Dict of node_id -> GRID objects.

        Returns:
            Tuple of (constrained_dof_set, enforced_disp_dict)
            where enforced_disp_dict maps DOF index -> enforced value.
        """
        constrained: Set[int] = set()
        enforced: Dict[int, float] = {}

        # Permanent SPCs from GRID PS field
        for nid, grid in model_nodes.items():
            if nid not in self._nid_to_index:
                continue
            if grid.ps:
                for ch in grid.ps:
                    comp = int(ch)
                    if 1 <= comp <= 6:
                        dof = self.get_dof(nid, comp)
                        constrained.add(dof)

        # SPC and SPC1 entries
        for spc_obj in spc_list:
            if hasattr(spc_obj, "constraints"):
                # SPC card: (node_id, components, enforced_value)
                for nid, comp_str, disp_val in spc_obj.constraints:
                    if nid not in self._nid_to_index:
                        continue
                    for ch in comp_str:
                        comp = int(ch)
                        if 1 <= comp <= 6:
                            dof = self.get_dof(nid, comp)
                            constrained.add(dof)
                            if abs(disp_val) > 0:
                                enforced[dof] = disp_val

            elif hasattr(spc_obj, "components"):
                # SPC1 card
                for nid in spc_obj.node_ids:
                    if nid not in self._nid_to_index:
                        continue
                    for ch in spc_obj.components:
                        comp = int(ch)
                        if 1 <= comp <= 6:
                            dof = self.get_dof(nid, comp)
                            constrained.add(dof)

        return constrained, enforced

