"""Tests for BDF field parsing."""

import pytest
from nastaero.bdf.cards import (
    nastran_float,
    nastran_int,
    parse_fixed8,
    parse_free,
    detect_format,
)


class TestNastranFloat:
    def test_standard_float(self):
        assert nastran_float("1.5") == 1.5

    def test_scientific_notation(self):
        assert nastran_float("1.5e3") == 1500.0
        assert nastran_float("1.5E-3") == 0.0015

    def test_nastran_implicit_exponent(self):
        assert nastran_float("1.5+3") == 1500.0
        assert nastran_float("1.5-3") == 0.0015

    def test_nastran_short_mantissa(self):
        assert nastran_float(".5+3") == 500.0
        assert nastran_float("7.+10") == 7e10

    def test_fortran_d_notation(self):
        assert nastran_float("1.5D3") == 1500.0
        assert nastran_float("1.5d-3") == 0.0015

    def test_blank_default(self):
        assert nastran_float("", default=0.0) == 0.0
        assert nastran_float("   ", default=42.0) == 42.0

    def test_integer_like(self):
        assert nastran_float("100") == 100.0

    def test_negative(self):
        assert nastran_float("-1.5+3") == -1500.0


class TestNastranInt:
    def test_basic(self):
        assert nastran_int("42") == 42

    def test_blank(self):
        assert nastran_int("", default=0) == 0
        assert nastran_int("   ", default=5) == 5


class TestFixedField:
    def test_parse_grid(self):
        line = "GRID    101             0.0     1.0     0.0             345     "
        fields = parse_fixed8(line)
        assert fields[0].strip() == "GRID"
        assert fields[1].strip() == "101"
        assert fields[3].strip() == "0.0"
        assert fields[4].strip() == "1.0"


class TestDetectFormat:
    def test_free_field(self):
        assert detect_format("GRID,101,,0.0,1.0,0.0,,345") == "free"

    def test_fixed8(self):
        assert detect_format("GRID    101             0.0     1.0") == "fixed8"

    def test_fixed16(self):
        assert detect_format("GRID*   101") == "fixed16"

