        line = "GRID    101             0.0     1.0     0.0             345     "
        fields = parse_fixed8(line)
        assert fields[0].strip() == "GRID"
        assert fields[1].strip() == "101"
        assert fields[3].strip() == "0.0"
        assert fields[4].strip() == "1.0"


class TestDetectFormat:
    def test_free_field(self):
        assert detect_format("GRID,101,,0.0,1.0,0.0,,345") == "free"

    def test_fixed8(self):
        assert detect_format("GRID    101             0.0     1.0") == "fixed8"

    def test_fixed16(self):
        assert detect_format("GRID*   101") == "fixed16"

