"""Global stiffness and mass matrix assembly."""
from __future__ import annotations
from typing import Dict, List
import numpy as np
import scipy.sparse as sp
from .dof_manager import DOFManager
from ..bdf.model import BDFModel
from ..elements.bar import CBarElement
from ..elements.quad4 import CQuad4Element
from ..elements.tria3 import CTria3Element
from ..config import logger

def assemble_global_matrices(model: BDFModel, dof_mgr: DOFManager):
    ndof = dof_mgr.total_dof
    rows_k, cols_k, vals_k = [], [], []
    rows_m, cols_m, vals_m = [], [], []
    n_assembled = 0

    for eid, elem in model.elements.items():
        try:
            if elem.type == "CBAR":
                ke, me, edofs = _assemble_cbar(elem, model, dof_mgr)
            elif elem.type == "CROD":
                ke, me, edofs = _assemble_crod(elem, model, dof_mgr)
            elif elem.type == "CQUAD4":
                ke, me, edofs = _assemble_cquad4(elem, model, dof_mgr)
            elif elem.type == "CTRIA3":
                ke, me, edofs = _assemble_ctria3(elem, model, dof_mgr)
            else:
                logger.debug("Element type %s not supported for assembly", elem.type)
                continue
        except Exception as exc:
            logger.warning("Error assembling element %d (%s): %s", eid, elem.type, exc)
            continue

        nd = len(edofs)
        for i in range(nd):
            for j in range(nd):
                if abs(ke[i,j]) > 1e-30:
                    rows_k.append(edofs[i]); cols_k.append(edofs[j]); vals_k.append(ke[i,j])
                if abs(me[i,j]) > 1e-30:
                    rows_m.append(edofs[i]); cols_m.append(edofs[j]); vals_m.append(me[i,j])
        n_assembled += 1

    # Concentrated masses (CONM2)
    for mid, mass_elem in model.masses.items():
        nid = mass_elem.node_id
        if nid not in dof_mgr._nid_to_index: continue
        node_dofs = dof_mgr.get_node_dofs(nid)
        for i in range(3):
            rows_m.append(node_dofs[i]); cols_m.append(node_dofs[i])
            vals_m.append(mass_elem.mass)
        # Rotational inertia if provided
        if mass_elem.I11 > 0:
            rows_m.append(node_dofs[3]); cols_m.append(node_dofs[3]); vals_m.append(mass_elem.I11)
        if mass_elem.I22 > 0:
            rows_m.append(node_dofs[4]); cols_m.append(node_dofs[4]); vals_m.append(mass_elem.I22)
        if mass_elem.I33 > 0:
            rows_m.append(node_dofs[5]); cols_m.append(node_dofs[5]); vals_m.append(mass_elem.I33)

    # RBE2 rigid elements (penalty approach)
    for rid, rbe in model.rigids.items():
        if rbe.type == "RBE2":
            _assemble_rbe2(rbe, model, dof_mgr, rows_k, cols_k, vals_k)

    logger.info("Assembled %d elements into global matrices (%d DOFs)", n_assembled, ndof)
    K = sp.coo_matrix((vals_k, (rows_k, cols_k)), shape=(ndof, ndof)).tocsc()
    M = sp.coo_matrix((vals_m, (rows_m, cols_m)), shape=(ndof, ndof)).tocsc()
    return K, M

def _assemble_cbar(elem, model, dof_mgr):
    prop = elem.property_ref; mat = prop.material_ref
    n1 = model.nodes[elem.node_ids[0]]; n2 = model.nodes[elem.node_ids[1]]
    if elem.g0 > 0 and elem.g0 in model.nodes:
        v_vector = model.nodes[elem.g0].xyz_global - n1.xyz_global
    else:
        v_vector = elem.x.copy()
        if np.linalg.norm(v_vector) < 1e-12: v_vector = np.array([0., 0., 1.])
    bar = CBarElement(n1.xyz_global, n2.xyz_global, v_vector, mat.E, mat.G, prop.A, prop.I1, prop.I2, prop.J, mat.rho, prop.nsm)
    return bar.stiffness_matrix(), bar.mass_matrix(), dof_mgr.get_element_dofs(elem.node_ids)

def _assemble_crod(elem, model, dof_mgr):
    prop = elem.property_ref; mat = prop.material_ref
    n1 = model.nodes[elem.node_ids[0]]; n2 = model.nodes[elem.node_ids[1]]
    diff = n2.xyz_global - n1.xyz_global; L = np.linalg.norm(diff)
    if L < 1e-12: raise ValueError(f"Zero-length CROD {elem.eid}")
    ex = diff / L; ea_l = mat.E * prop.A / L
    ke = np.zeros((12, 12)); me = np.zeros((12, 12))
    ex_out = np.outer(ex, ex)
    ke[0:3,0:3] = ea_l*ex_out; ke[0:3,6:9] = -ea_l*ex_out
    ke[6:9,0:3] = -ea_l*ex_out; ke[6:9,6:9] = ea_l*ex_out
    m_half = (mat.rho * prop.A * L) / 2.0
    for i in range(3): me[i,i] = m_half; me[i+6,i+6] = m_half
    return ke, me, dof_mgr.get_element_dofs(elem.node_ids)

def _assemble_cquad4(elem, model, dof_mgr):
    prop = elem.property_ref; mat = prop.material_ref
    node_xyz = np.array([model.nodes[nid].xyz_global for nid in elem.node_ids])
    q = CQuad4Element(node_xyz, mat.E, mat.nu, prop.t, mat.rho)
    return q.stiffness_matrix(), q.mass_matrix(), dof_mgr.get_element_dofs(elem.node_ids)

def _assemble_ctria3(elem, model, dof_mgr):
    prop = elem.property_ref; mat = prop.material_ref
    node_xyz = np.array([model.nodes[nid].xyz_global for nid in elem.node_ids])
    tri = CTria3Element(node_xyz, mat.E, mat.nu, prop.t, mat.rho)
    return tri.stiffness_matrix(), tri.mass_matrix(), dof_mgr.get_element_dofs(elem.node_ids)

def _assemble_rbe2(rbe, model, dof_mgr, rows_k, cols_k, vals_k):
    """Assemble RBE2 using penalty method. Large stiffness coupling independent to dependent DOFs."""
    penalty = 1e12  # large penalty stiffness
    ind_nid = rbe.independent_node
    if ind_nid not in dof_mgr._nid_to_index: return
    for dep_nid in rbe.dependent_nodes:
        if dep_nid not in dof_mgr._nid_to_index: continue
        for ch in rbe.components:
            comp = int(ch)
            if comp < 1 or comp > 6: continue
            ind_dof = dof_mgr.get_dof(ind_nid, comp)
            dep_dof = dof_mgr.get_dof(dep_nid, comp)
            # K_penalty: penalty * [[1, -1], [-1, 1]]
            rows_k.extend([ind_dof, ind_dof, dep_dof, dep_dof])
            cols_k.extend([ind_dof, dep_dof, ind_dof, dep_dof])
            vals_k.extend([penalty, -penalty, -penalty, penalty])

"""DOF (Degree of Freedom) manager."""
from __future__ import annotations
from typing import Dict, List, Set, Tuple
import numpy as np

class DOFManager:
    def __init__(self, node_ids: List[int]) -> None:
        self._sorted_nids = sorted(node_ids)
        self._nid_to_index: Dict[int, int] = {nid: idx for idx, nid in enumerate(self._sorted_nids)}
        self._ndof_per_node = 6
        self._total_dof = len(self._sorted_nids) * self._ndof_per_node

    @property
    def total_dof(self) -> int: return self._total_dof
    @property
    def n_nodes(self) -> int: return len(self._sorted_nids)
    @property
    def node_ids(self) -> List[int]: return self._sorted_nids

    def get_dof(self, node_id: int, component: int) -> int:
        return self._nid_to_index[node_id] * self._ndof_per_node + (component - 1)

    def get_node_dofs(self, node_id: int) -> List[int]:
        base = self._nid_to_index[node_id] * self._ndof_per_node
        return list(range(base, base + 6))

    def get_element_dofs(self, node_ids: List[int]) -> List[int]:
        dofs: List[int] = []
        for nid in node_ids:
            dofs.extend(self.get_node_dofs(nid))
        return dofs

    def get_constrained_dofs(self, spc_list: list, model_nodes: dict) -> Tuple[Set[int], Dict[int, float]]:
        constrained: Set[int] = set()
        enforced: Dict[int, float] = {}
        for nid, grid in model_nodes.items():
            if nid not in self._nid_to_index: continue
            if grid.ps:
                for ch in grid.ps:
                    comp = int(ch)
                    if 1 <= comp <= 6:
                        constrained.add(self.get_dof(nid, comp))
        for spc_obj in spc_list:
            if hasattr(spc_obj, "constraints"):
                for nid, comp_str, disp_val in spc_obj.constraints:
                    if nid not in self._nid_to_index: continue
                    for ch in comp_str:
                        comp = int(ch)
                        if 1 <= comp <= 6:
                            dof = self.get_dof(nid, comp)
                            constrained.add(dof)
                            if abs(disp_val) > 0: enforced[dof] = disp_val
            elif hasattr(spc_obj, "components"):
                for nid in spc_obj.node_ids:
                    if nid not in self._nid_to_index: continue
                    for ch in spc_obj.components:
                        comp = int(ch)
                        if 1 <= comp <= 6:
                            constrained.add(self.get_dof(nid, comp))
        return constrained, enforced

"""Assemble the global load vector from parsed load cards."""
from __future__ import annotations
from typing import Dict
import numpy as np
from .dof_manager import DOFManager
from ..bdf.model import BDFModel, Subcase
from ..config import logger

def assemble_load_vector(model: BDFModel, subcase: Subcase, dof_mgr: DOFManager) -> np.ndarray:
    ndof = dof_mgr.total_dof; F = np.zeros(ndof)
    load_id = subcase.load_id
    if load_id == 0: return F
    if load_id in model.load_combinations:
        lc = model.load_combinations[load_id]
        for sf, lid in zip(lc.scale_factors, lc.load_ids):
            if lid in model.loads:
                _add_load_set(F, model, model.loads[lid], lc.scale * sf, dof_mgr)
    elif load_id in model.loads:
        _add_load_set(F, model, model.loads[load_id], 1.0, dof_mgr)
    else:
        logger.warning("Load set %d not found", load_id)
    return F

def _add_load_set(F, model, load_list, scale, dof_mgr):
    for load in load_list:
        if load.type == "FORCE":
            fv = load.get_force_vector() * scale
            nd = dof_mgr.get_node_dofs(load.node_id)
            F[nd[0]] += fv[0]; F[nd[1]] += fv[1]; F[nd[2]] += fv[2]
        elif load.type == "MOMENT":
            mv = load.get_moment_vector() * scale
            nd = dof_mgr.get_node_dofs(load.node_id)
            F[nd[3]] += mv[0]; F[nd[4]] += mv[1]; F[nd[5]] += mv[2]
        elif load.type == "GRAV":
            _add_gravity_load(F, model, load, scale, dof_mgr)

def _add_gravity_load(F, model, grav_load, scale, dof_mgr):
    accel = grav_load.get_acceleration_vector() * scale
    node_mass: Dict[int, float] = {}
    for eid, elem in model.elements.items():
        if not hasattr(elem, "property_ref") or elem.property_ref is None: continue
        prop = elem.property_ref; mat = getattr(prop, "material_ref", None)
        if mat is None or mat.rho <= 0: continue
        if elem.type in ("CBAR", "CROD"):
            n1 = model.nodes[elem.node_ids[0]]; n2 = model.nodes[elem.node_ids[1]]
            L = np.linalg.norm(n2.xyz_global - n1.xyz_global)
            em = mat.rho * prop.A * L + getattr(prop, "nsm", 0) * L
            for nid in elem.node_ids: node_mass[nid] = node_mass.get(nid, 0.) + em/2
        elif elem.type in ("CQUAD4", "CTRIA3"):
            xyz = np.array([model.nodes[nid].xyz_global for nid in elem.node_ids])
            if elem.type == "CQUAD4":
                d13 = xyz[2]-xyz[0]; d24 = xyz[3]-xyz[1]
                area = 0.5*np.linalg.norm(np.cross(d13, d24))
            else:
                v1 = xyz[1]-xyz[0]; v2 = xyz[2]-xyz[0]
                area = 0.5*np.linalg.norm(np.cross(v1, v2))
            em = mat.rho * prop.t * area
            nn = len(elem.node_ids)
            for nid in elem.node_ids: node_mass[nid] = node_mass.get(nid, 0.) + em/nn
    for mid, me in model.masses.items():
        node_mass[me.node_id] = node_mass.get(me.node_id, 0.) + me.mass
    for nid, m in node_mass.items():
        if nid not in dof_mgr._nid_to_index: continue
        nd = dof_mgr.get_node_dofs(nid)
        F[nd[0]] += m*accel[0]; F[nd[1]] += m*accel[1]; F[nd[2]] += m*accel[2]

"""BDF card field parsing: fixed-8, fixed-16, and free-field formats.

Nastran BDF cards use 80-column lines with fields:
- Fixed 8-char: 10 fields of 8 characters each
- Fixed 16-char (large field): card name ends with *, fields are 16 chars
- Free-field: comma-separated values

Nastran float quirks:
- '1.5+3' means 1.5e3
- '1.5-3' means 1.5e-3
- '.5+3' means 0.5e3
- '1.5D3' means 1.5e3 (FORTRAN double)
- Blank or empty -> default value
"""
from __future__ import annotations
import re
from typing import List

_NASTRAN_FLOAT_RE = re.compile(
    r"^([+-]?\d*\.?\d*)"
    r"([+-])"
    r"(\d+)$"
)

def nastran_float(field: str, default: float = 0.0) -> float:
    s = field.strip()
    if not s:
        return default
    s = s.replace("d", "e").replace("D", "e")
    try:
        return float(s)
    except ValueError:
        pass
    m = _NASTRAN_FLOAT_RE.match(s)
    if m:
        mantissa = m.group(1) if m.group(1) else "0"
        exp_sign = m.group(2)
        exp_digits = m.group(3)
        try:
            return float(f"{mantissa}e{exp_sign}{exp_digits}")
        except ValueError:
            pass
    raise ValueError(f"Cannot parse Nastran float: '{field}'")

def nastran_int(field: str, default: int = 0) -> int:
    s = field.strip()
    if not s:
        return default
    return int(s)

def nastran_string(field: str, default: str = "") -> str:
    s = field.strip()
    return s if s else default

def parse_fixed8(line: str) -> List[str]:
    padded = line.ljust(80)
    return [padded[i:i + 8] for i in range(0, 80, 8)]

def parse_fixed16(lines: List[str]) -> List[str]:
    fields = []
    for line in lines:
        padded = line.ljust(80)
        if not fields:
            fields.append(padded[0:8])
            fields.append(padded[8:24])
            fields.append(padded[24:40])
            fields.append(padded[40:56])
            fields.append(padded[56:72])
        else:
            fields.append(padded[8:24])
            fields.append(padded[24:40])
            fields.append(padded[40:56])
            fields.append(padded[56:72])
    return fields

def parse_free(line: str) -> List[str]:
    return [f.strip() for f in line.split(",")]

def detect_format(line: str) -> str:
    if "," in line:
        return "free"
    card_name = line[:8].strip()
    if card_name.endswith("*"):
        return "fixed16"
    return "fixed8"

def parse_card_fields(lines: List[str]) -> List[str]:
    if not lines:
        return []
    fmt = detect_format(lines[0])
    if fmt == "free":
        all_text = ""
        for line in lines:
            all_text += line
        return parse_free(all_text)
    if fmt == "fixed16":
        return parse_fixed16(lines)
    all_fields: List[str] = []
    for i, line in enumerate(lines):
        raw = parse_fixed8(line)
        if i == 0:
            all_fields.extend(raw[:9])
        else:
            all_fields.extend(raw[1:9])
    return all_fields

"""Bulk data card dispatcher."""
from __future__ import annotations
from typing import List
from .model import BDFModel
from .cards.grid import GRID
from .cards.coord import CORD2R
from .cards.elements import CBAR, CROD, CQUAD4, CTRIA3
from .cards.properties import PBAR, PROD, PSHELL, PSOLID
from .cards.materials import MAT1
from .cards.loads import FORCE, MOMENT, GRAV, LoadCombination
from .cards.constraints import SPC, SPC1
from .cards.mass import CONM2
from .cards.eigrl import EIGRL
from .cards.rbe import RBE2
from .cards.param import PARAM
from ..config import logger

def parse_bulk_card(fields: List[str], model: BDFModel) -> None:
    if not fields: return
    card_name = fields[0].strip().upper().rstrip("*")
    try:
        if card_name == "GRID":
            g = GRID.from_fields(fields); model.nodes[g.nid] = g
        elif card_name == "CORD2R":
            c = CORD2R.from_fields(fields); model.coords[c.cid] = c
        elif card_name == "CBAR":
            e = CBAR.from_fields(fields); model.elements[e.eid] = e
        elif card_name == "CROD":
            e = CROD.from_fields(fields); model.elements[e.eid] = e
        elif card_name == "CQUAD4":
            e = CQUAD4.from_fields(fields); model.elements[e.eid] = e
        elif card_name == "CTRIA3":
            e = CTRIA3.from_fields(fields); model.elements[e.eid] = e
        elif card_name == "PBAR":
            p = PBAR.from_fields(fields); model.properties[p.pid] = p
        elif card_name == "PROD":
            p = PROD.from_fields(fields); model.properties[p.pid] = p
        elif card_name == "PSHELL":
            p = PSHELL.from_fields(fields); model.properties[p.pid] = p
        elif card_name == "PSOLID":
            p = PSOLID.from_fields(fields); model.properties[p.pid] = p
        elif card_name == "MAT1":
            m = MAT1.from_fields(fields); model.materials[m.mid] = m
        elif card_name == "FORCE":
            l = FORCE.from_fields(fields); model.loads.setdefault(l.sid, []).append(l)
        elif card_name == "MOMENT":
            l = MOMENT.from_fields(fields); model.loads.setdefault(l.sid, []).append(l)
        elif card_name == "GRAV":
            l = GRAV.from_fields(fields); model.loads.setdefault(l.sid, []).append(l)
        elif card_name == "LOAD":
            lc = LoadCombination.from_fields(fields); model.load_combinations[lc.sid] = lc
        elif card_name == "SPC":
            s = SPC.from_fields(fields); model.spcs.setdefault(s.sid, []).append(s)
        elif card_name == "SPC1":
            s = SPC1.from_fields(fields); model.spcs.setdefault(s.sid, []).append(s)
        elif card_name == "CONM2":
            m = CONM2.from_fields(fields); model.masses[m.eid] = m
        elif card_name == "EIGRL":
            e = EIGRL.from_fields(fields); model.eigrls[e.sid] = e
        elif card_name == "RBE2":
            r = RBE2.from_fields(fields); model.rigids[r.eid] = r
        elif card_name == "PARAM":
            name, value = PARAM.from_fields(fields); model.params[name] = value
        else:
            logger.debug("Unsupported card: %s", card_name)
    except (IndexError, ValueError) as exc:
        logger.warning("Error parsing %s: %s", card_name, exc)

"""Structural element card parsers."""
from __future__ import annotations
from dataclasses import dataclass, field
from typing import Any, List, Optional
import numpy as np
from ..field_parser import nastran_int, nastran_float

@dataclass
class CBAR:
    eid: int = 0; pid: int = 0
    node_ids: List[int] = field(default_factory=list)
    g0: int = 0
    x: np.ndarray = field(default_factory=lambda: np.array([0., 0., 0.]))
    offt: str = "GGG"; pa: int = 0; pb: int = 0
    wa: np.ndarray = field(default_factory=lambda: np.zeros(3))
    wb: np.ndarray = field(default_factory=lambda: np.zeros(3))
    property_ref: Optional[Any] = None
    node_refs: List[Any] = field(default_factory=list)
    @property
    def type(self) -> str: return "CBAR"
    @classmethod
    def from_fields(cls, fields: List[str]) -> CBAR:
        e = cls(); e.eid = nastran_int(fields[1]); e.pid = nastran_int(fields[2])
        e.node_ids = [nastran_int(fields[3]), nastran_int(fields[4])]
        f5 = fields[5].strip() if len(fields) > 5 else ""
        if f5:
            try:
                if "." not in f5 and "+" not in f5 and "-" not in f5[1:]:
                    e.g0 = int(f5)
                else:
                    raise ValueError()
            except (ValueError, IndexError):
                e.x = np.array([nastran_float(fields[5]),
                    nastran_float(fields[6]) if len(fields) > 6 else 0.0,
                    nastran_float(fields[7]) if len(fields) > 7 else 0.0])
        if len(fields) > 8:
            offt_str = fields[8].strip()
            if offt_str: e.offt = offt_str
        if len(fields) > 9: e.pa = nastran_int(fields[9])
        if len(fields) > 10: e.pb = nastran_int(fields[10])
        return e

@dataclass
class CROD:
    eid: int = 0; pid: int = 0; node_ids: List[int] = field(default_factory=list)
    property_ref: Optional[Any] = None; node_refs: List[Any] = field(default_factory=list)
    @property
    def type(self) -> str: return "CROD"
    @classmethod
    def from_fields(cls, fields: List[str]) -> CROD:
        e = cls(); e.eid = nastran_int(fields[1]); e.pid = nastran_int(fields[2])
        e.node_ids = [nastran_int(fields[3]), nastran_int(fields[4])]
        return e

@dataclass
class CQUAD4:
    eid: int = 0; pid: int = 0
    node_ids: List[int] = field(default_factory=list)  # [G1, G2, G3, G4]
    theta_mcid: float = 0.0  # Material angle or coord system ID
    zoffs: float = 0.0       # Z offset from reference plane
    property_ref: Optional[Any] = None
    node_refs: List[Any] = field(default_factory=list)
    @property
    def type(self) -> str: return "CQUAD4"
    @classmethod
    def from_fields(cls, fields: List[str]) -> CQUAD4:
        e = cls(); e.eid = nastran_int(fields[1]); e.pid = nastran_int(fields[2])
        e.node_ids = [nastran_int(fields[3]), nastran_int(fields[4]),
                      nastran_int(fields[5]), nastran_int(fields[6])]
        if len(fields) > 7: e.theta_mcid = nastran_float(fields[7])
        if len(fields) > 8: e.zoffs = nastran_float(fields[8])
        return e

@dataclass
class CTRIA3:
    eid: int = 0; pid: int = 0
    node_ids: List[int] = field(default_factory=list)  # [G1, G2, G3]
    theta_mcid: float = 0.0
    zoffs: float = 0.0
    property_ref: Optional[Any] = None
    node_refs: List[Any] = field(default_factory=list)
    @property
    def type(self) -> str: return "CTRIA3"
    @classmethod
    def from_fields(cls, fields: List[str]) -> CTRIA3:
        e = cls(); e.eid = nastran_int(fields[1]); e.pid = nastran_int(fields[2])
        e.node_ids = [nastran_int(fields[3]), nastran_int(fields[4]), nastran_int(fields[5])]
