@dataclass
class RBE3:
    """Interpolation constraint element (weighted average).
    RBE3  EID       REFGRID REFC  WT1  C1  G1,1 G1,2 ...
                    WT2  C2  G2,1 G2,2 ...
    The reference node (REFGRID) is dependent; its motion is the weighted
    average of the independent nodes.
    """
    eid: int = 0
    refgrid: int = 0
    refc: str = "123456"
    weight_sets: List[Tuple[float, str, List[int]]] = field(default_factory=list)
    property_ref: Optional[Any] = None
    node_refs: List[Any] = field(default_factory=list)

    @property
    def type(self) -> str: return "RBE3"
    @property
    def node_ids(self) -> List[int]:
        ids = [self.refgrid]
        for _, _, nids in self.weight_sets:
            ids.extend(nids)
        return ids

    @classmethod
    def from_fields(cls, fields: List[str]) -> RBE3:
        r = cls()
        r.eid = nastran_int(fields[1])
        # fields[2] is blank
        r.refgrid = nastran_int(fields[3])
        r.refc = fields[4].strip()
        # Parse weight sets: WT, C, G1, G2, ..., WT, C, G1, ...
        i = 5
        raw = [f.strip() for f in fields[5:]]
        idx = 0
        while idx < len(raw):
            wt_str = raw[idx]
            if not wt_str:
                idx += 1; continue
            # Check if this looks like a weight (float)
            try:
                wt = float(wt_str.replace("d", "e").replace("D", "e"))
            except ValueError:
                idx += 1; continue
            if idx + 1 >= len(raw):
                break
            comp = raw[idx + 1]
            if not comp:
                idx += 2; continue
            idx += 2
            nids: List[int] = []
            while idx < len(raw):
                s = raw[idx]
                if not s:
                    idx += 1; continue
                # Check if next token is a new weight (has a '.') or integer node
                try:
                    nid = int(s)
                    nids.append(nid)
                    idx += 1
                except ValueError:
                    break  # New weight set
            if nids:
                r.weight_sets.append((wt, comp, nids))
        return r

