            while j < len(fields):
                gs = fields[j].strip()
                if not gs:
                    j += 1; continue
                try:
                    gid = int(gs)
                    grids.append(gid)
                    j += 1
                except ValueError:
                    # Next token is not a grid ID - might be next weight
                    break
            if grids:
                r.weight_sets.append((wt, comp, grids))
            i = j
        return r

