            pl.show(screenshot=screenshot, auto_close=True)
        else:
            pl.show(auto_close=False)
            pl.screenshot(screenshot, transparent_background=False)
            pl.close()
        print(f"Screenshot saved: {screenshot}")
    else:
        if not off_screen:
            pl.show()
        else:
            pl.show(auto_close=True)

